return {rwnpc01={id="rwnpc01",title="BLU时间缺失大师NOR",dsc="看模样像是个幼童，但因为实在太小只，所以判断不清性别。明明看上去是个小孩，说话的口气却是个十足的大人。小小的身子在桌子前忙得团团转，根本停不下来。",sex="野兽",age=3,looks=25,showequip={},withCorpse=0},rwnpc02={id="rwnpc02",dsc="他正是红松阁的表面首脑，实为高级打杂， 每天身份于压榨别人和被压榨之间来回切换，练就出一身厚脸皮神功。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc03={id="rwnpc03",dsc="此人曾是戍卫边疆的武官，身长八尺有余，豹头环眼，壮如蛮牛，皮肤黝黑，下颚上留有钢针般遒劲的浓密胡须。",sex="男",age=49,looks=18,showequip={},withCorpse=0},rwnpc04={id="rwnpc04",dsc="此人头戴斗笠看不清面容，但其气息内敛，应当是个高手。",sex="野兽",age=30,looks=20,showequip={},withCorpse=0},rwnpc05={id="rwnpc05",title="BLU工具人NOR",dsc="她穿着宽松大袍，带着一个白色的面具，看不出样貌。",sex="女",age=23,looks=10,showequip={},withCorpse=0},rwnpc06={id="rwnpc06",dsc="此人身着黑衣，头戴黑纱斗笠，但其气息内敛，应当是个高手。",sex="野兽",age=30,looks=20,showequip={},withCorpse=0},rwnpc07={id="rwnpc07",dsc="此人身着蓑衣，头戴斗笠看不清面容，手抱长刀，看起来是个高手。",sex="野兽",age=30,looks=20,showequip={},withCorpse=0},rwnpc11={id="rwnpc11",dsc="他清爽利落，一身文人打扮，手持一支徽笔，指点天下，隐隐有睥睨之姿。",sex="男",age=30,looks=27,showequip={},withCorpse=0},rwnpc12={id="rwnpc12",dsc="她是负责接引游客的接引人。时而安静，低头处理自己的事物，时而活泼，与游客们打成一片。",sex="女",age=26,looks=22,showequip={},withCorpse=0},rwnpc13={id="rwnpc13",dsc="他手如鸡爪，面若鼠狼，身似骷髅。他双腿已断，似乎是从悬崖上摔落到谷底，只能以谷底的蛇虫鼠蚁为食。",sex="男",age=60,looks=12,showequip={},withCorpse=0},rwnpc14={id="rwnpc14",dsc="他手臂绘有淡淡的刺青，一头长发用木簪盘起，虽然身为男子，长相却比寻常女子还要秀气。",sex="男",age=20,looks=24,showequip={},withCorpse=0},rwnpc15={id="rwnpc15",dsc="他左手一支笔，右手一支笔。左手细笔急促，将面具仔细轻描；右手长笔飒挥，将山水描摹于纸上。",sex="男",age=20,looks=19,showequip={},withCorpse=0},rwnpc16={id="rwnpc16",dsc="他容貌如画，漂亮得根本就不似真人这种容貌，这种风仪，根本就已经超越了一切人类的美丽。这种超越的男女，超越了世俗的美态，竟是已不能用言词来形容。",sex="男",age=23,looks=28,showequip={},withCorpse=0},rwnpc17={id="rwnpc17",dsc="只见他白衣洁净，如琼枝一树，栽种在青山绿水之间，尽得天地之精华；又似昆仑美玉，落于东南一隅，散发着淡淡华彩，不由得让人一呆。",sex="男",age=34,looks=30,showequip={},withCorpse=0},rwnpc18={id="rwnpc18",dsc="盛唐阁二阁主，平日虽不坐镇这阁内，但其威严依然让属下噤若寒蝉。",sex="男",age=30,looks=29,showequip={},withCorpse=0},rwnpc20={id="rwnpc20",dsc="他宽衣宽袍，戴着一个木质面具，看不出男女，也看不清他什么模样。",sex="野兽",age=23,looks=10,showequip={},withCorpse=0},rwnpc21={id="rwnpc21",dsc="她身着带兜帽的白色长袍，身边常伴一猫一狗，身形很是敏捷。",sex="女",age=18,looks=22,showequip={},withCorpse=0},rwnpc22={id="rwnpc22",dsc="此人黑衣蒙面，在松林里鬼鬼祟祟。",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc23={id="rwnpc23",dsc="他身着一袭洁白的长衫，长衫上绣有淡雅的竹叶图案，为他增添了几分书卷气。",sex="男",age=30,looks=22,showequip={},withCorpse=0},rwnpc24={id="rwnpc24",dsc="他一身青袍，站若松竹，腰间佩戴着一柄长剑。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc25={id="rwnpc25",dsc="他身着一袭素色长衫，怀抱一柄长剑，气度不凡。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc26={id="rwnpc26",dsc="他一身黑衫，面含戾气，似乎很容易动怒。",sex="男",age=30,looks=18,showequip={},withCorpse=0},rwnpc27={id="rwnpc27",dsc="他瞧着像是江南人士，手执书卷，彬彬有礼。",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc28={id="rwnpc28",dsc="他身着一袭深蓝色布衫，手中书卷已有些陈旧。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc29={id="rwnpc29",dsc="他是一位稍显沧桑的中年道人，面上沉着冷静，不苟言笑。",sex="男",age=35,looks=19,showequip={},withCorpse=0},rwnpc30={id="rwnpc30",dsc="他是一位未通世故的青年道人，脸上挂着孩儿般的微笑。",sex="男",age=20,looks=20,showequip={},withCorpse=0},rwnpc31={id="rwnpc31",dsc="此人头戴斗笠看不清面容，但其气息内敛，应当是个高手。",sex="野兽",age=30,looks=17,showequip={},withCorpse=0},rwnpc32={id="rwnpc32",dsc="此人身着蓑衣，头戴斗笠看不清面容，手抱长刀，看起来是个高手。",sex="野兽",age=30,looks=17,showequip={},withCorpse=0},rwnpc33={id="rwnpc33",dsc="一个须发皆白的老者，精神矍铄，满面红光。",sex="男",age=64,looks=23,showequip={},withCorpse=0},rwnpc34={id="rwnpc34",dsc="她一身水蓝长裙，手里拿着书卷，气质文雅端庄。",sex="女",age=20,looks=20,showequip={},withCorpse=0},rwnpc35={id="rwnpc35",dsc="她一身黄布裙，亦步亦趋的跟着水蓝长裙的女子。",sex="女",age=17,looks=18,showequip={},withCorpse=0},rwnpc36={id="rwnpc36",dsc="他是附近有名的郎中，背着一个药箱，坐在路边的树下。",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc37={id="rwnpc37",dsc="应是受邀而来的侠士，却陷入争执之中。",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc38={id="rwnpc38",dsc="山庄的守卫，身着短打白袍，干净利落。",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc39={id="rwnpc39",dsc="他着一身深灰色的 长袍，神情有些倨傲，眼睛在周围人身上扫来扫去。",sex="男",age=30,looks=13,showequip={},withCorpse=0},rwnpc40={id="rwnpc40",dsc="应是来山庄游玩之人。",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc41={id="rwnpc41",dsc="他是一名强盗，却穿金带银，就连手上的宝刀都嵌满宝晶玉石，华贵得不可思议。",sex="男",age=30,looks=25,showequip={},withCorpse=0}}0000000000